module parity_8bit (
    input [7:0] in,
    output out
);

wire w1, w2, w3, w4, w5, w6;

assign w1 = in[1] ^ in[0];
assign w2 = ~(in[3] ^ in[2]);
assign w3 = w1 ^ w2;

assign w4 = in[5] ^ in[4];
assign w5 = ~(in[7] ^ in[6]);
assign w6 = w4 ^ w5;

assign out = w3 ^ w6;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire nsel0;
wire a, b, c, d;
wire e, f;
wire g;
wire h, i;

assign nsel0 = ~sel[0];

assign a = ~(sel[1] & sel[0]);
assign b = ~(sel[1] & nsel0);

assign c = ~(in[1] & sel[0]);
assign d = ~(in[3] & sel[0]);

assign e = ~(a & b);
assign f = ~(c & b);

assign g = c | d;

assign h = e | f;
assign i = h | g;

assign out = i;

endmodule

module majority (
    input a, b, c,
    output out
);

wire ab, ac, bc, x;

assign ab = a & b;
assign ac = a & c;
assign bc = b & c;
assign x  = ab | ac;
assign out = x | bc;

endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

assign gray[3] = binary[3];
assign gray[2] = binary[3] ^ binary[2];
assign gray[1] = binary[2] ^ binary[1];
assign gray[0] = binary[1] ^ binary[0];

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

assign out[0] = ~(in[1] | in[0]);
assign out[1] = ~(in[1] & in[0]);
assign out[2] = ~(in[1] & in[0]);
assign out[3] =  (in[1] & in[0]);

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);
    always @(*) begin
        code[1] = in[2] | in[3];
        code[0] = in[3] | (in[1] & ~in[2]);
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

wire rst;
wire q0, q1;
wire d1;
wire nstate0;
wire nreset_fb;

assign rst = reset | nreset_fb;
assign d1 = q0 ^ q1;
assign nstate0 = ~q0;
assign nreset_fb = ~(q1 & q0);

assign state = {q1, nstate0};

S_SDFF_PP0_ ff0 (
    .C(clk),
    .D(nstate0),
    .R(rst),
    .Q(q0)
);

S_SDFF_PP0_ ff1 (
    .C(clk),
    .D(d1),
    .R(rst),
    .Q(q1)
);

endmodule

module S_SDFF_PP0_ (
    input C,
    input D,
    input R,
    output reg Q
);
    always @(posedge C or posedge R) begin
        if (R)
            Q <= 1'b0;
        else
            Q <= D;
    end
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg q0, q1, q2;

    wire d0, d1, d2;

    assign d0 = q0 | reset;
    assign d1 = ~(q0 & reset);
    assign d2 = ~(q1 & reset);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q0 <= 1'b1;
            q1 <= 1'b1;
            q2 <= 1'b0;
        end else begin
            q0 <= d0;
            q1 <= d1;
            q2 <= d2;
        end
    end

    assign light[0] = ~((~(q1 & q2)) & (~(q1 & q2)));
    assign light[1] = ~((~(q1 | q2)) & q2);
    assign light[2] = q2 | reset;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

wire q1, q0;
wire nq1, nq0;
wire d1, d0;

assign nq1 = ~q1;
assign nq0 = ~q0;

// Next-state logic derived from the diagram
assign d1 = (q1 & ~q0) | (~q1 & q0 & down_request) | (q1 & q0 & ~up_request);
assign d0 = (~q1 & ~q0 & up_request) | (~q1 & q0) | (q1 & ~q0 & ~down_request);

assign state = {q1, q0};

s_DFF_PP0 ff1 (
    .D(d1),
    .C(clk),
    .R(reset),
    .Q(q1)
);

s_DFF_PP0 ff0 (
    .D(d0),
    .C(clk),
    .R(reset),
    .Q(q0)
);

endmodule

module s_DFF_PP0 (
    input D, C, R,
    output reg Q
);
    always @(posedge C or posedge R) begin
        if (R)
            Q <= 1'b0;
        else
            Q <= D;
    end
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

wire q0, q1;
wire n1, n2, n3, n4, n5, n6, n7, n8;

// Top state bit logic
assign n1 = ~(q0 | item_selected);
assign n2 = ~(n1 & q1);

// Bottom state bit logic
assign n3 = ~(q0 | coin_inserted);
assign n4 = n3 | q1;
assign n5 = ~(n4 & coin_inserted);

// Reset logic
assign n6 = q1 | q0;
assign n7 = ~(n6 | reset);
assign n8 = ~(q1 | reset);

dffrs ff0 (
    .clk(clk),
    .d(n5),
    .r(n7),
    .q(q0)
);

dffrs ff1 (
    .clk(clk),
    .d(n2),
    .r(n5),
    .q(q1)
);

assign state = {q1, q0};

endmodule

module dffrs (
    input clk,
    input d,
    input r,
    output reg q
);
    always @(posedge clk or posedge r) begin
        if (r)
            q <= 1'b0;
        else
            q <= d;
    end
endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    assign out = in_0 ** in_1;
endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

wire [15:0] x;
assign x = in_0[15] ? (~in_0 + 16'sd1) : in_0;

reg [7:0] y;
always @* begin
    if (x[15])      y = 8'd15;
    else if (x[14]) y = 8'd14;
    else if (x[13]) y = 8'd13;
    else if (x[12]) y = 8'd12;
    else if (x[11]) y = 8'd11;
    else if (x[10]) y = 8'd10;
    else if (x[9])  y = 8'd9;
    else if (x[8])  y = 8'd8;
    else if (x[7])  y = 8'd7;
    else if (x[6])  y = 8'd6;
    else if (x[5])  y = 8'd5;
    else if (x[4])  y = 8'd4;
    else if (x[3])  y = 8'd3;
    else if (x[2])  y = 8'd2;
    else if (x[1])  y = 8'd1;
    else            y = 8'd0;
end

assign out = $signed(y);

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);

assign out = a + b;

endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);
    assign out = a * b;
endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    assign diff = a - b;
endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);

assign and_out = a & b;
assign or_out  = a | b;
assign xor_out = a ^ b;

endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

assign out = in << shift;

endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);

assign out = ~in;

endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

assign out = (in << shift) | (in >> (3'd8 - shift));

endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);

assign out = in_0[15] ? 16'sd0 : in_0;

endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

wire n0;
wire w_a, w_b, w_c, w_d, w_e, w_f, w_g, w_h, w_i, w_j;

// Top output
assign n0 = ~data_in[0];
assign data_out[0] = n0;

// Upper logic
assign w_a = ~(data_in[1] | data_in[2]);
assign data_out[1] = ~(data_in[1] ^ data_in[2]);
assign data_out[2] = ~(w_a ^ data_in[5]);

assign w_b = ~(data_in[5] & w_a);
assign data_out[3] = w_b ^ data_in[5];

// Middle logic
assign w_c = ~(data_in[3] & data_in[4]);
assign w_d = w_c | w_a;
assign data_out[4] = ~(w_d ^ data_in[5]);

assign w_e = ~(data_in[5] & w_d);
assign data_out[5] = w_e ^ data_in[6];

// Lower logic
assign data_out[6] = ~(data_in[6] ^ w_d);

assign w_f = ~(data_in[4] & data_in[7]);
assign w_g = w_f | data_in[6];
assign w_h = ~(w_g & data_in[7]);
assign data_out[7] = w_h ^ data_in[7];

endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

wire n0;
wire x1;
wire a1;
wire x2;
wire o3;
wire x3;
wire x6;
wire n10;
wire n11;
wire n12;
wire n13;
wire n14;
wire n15;
wire n16;
wire x7;

assign n0  = ~data_in[0];
assign x1  = data_in[0] ^ data_in[1];
assign a1  = data_in[2] & data_in[3];
assign x2  = a1 ^ data_in[4];
assign o3  = data_in[4] | data_in[5];
assign x3  = o3 ^ data_in[6];
assign x6  = ~(data_in[4] ^ data_in[5]);

assign n10 = ~(data_in[3] & data_in[4]);
assign n11 = ~(data_in[2] | data_in[5]);
assign n12 = ~(n10 & n11);
assign n13 = ~(data_in[2] & n12);
assign n14 = ~(n12 | data_in[6]);
assign n15 = ~(data_in[6] & data_in[7]);
assign n16 = ~(n15 | data_in[0]);
assign x7  = n16 ^ data_in[1];

assign data_out[0] = n0;
assign data_out[1] = x1;
assign data_out[2] = x2;
assign data_out[3] = x3;
assign data_out[4] = 1'b0;
assign data_out[5] = n14 ^ data_in[7];
assign data_out[6] = x6;
assign data_out[7] = x7;

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [3:0] left, right;
    wire [3:0] f_out;

    assign left  = data_in[7:4];
    assign right = data_in[3:0];

    assign f_out[3] = right[0] ^ KEY[3];
    assign f_out[2] = ~(right[1] ^ KEY[2]);
    assign f_out[1] = right[2] ^ KEY[1];
    assign f_out[0] = ~(right[3] ^ KEY[0]);

    assign data_out[7:4] = right;
    assign data_out[3] = left[3] ^ f_out[3];
    assign data_out[2] = left[2] ^ f_out[2];
    assign data_out[1] = left[1] ^ f_out[1];
    assign data_out[0] = left[0] ^ f_out[0];

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);

reg q;

always @(posedge clk or posedge rst) begin
    if (rst)
        q <= 1'b0;
    else
        q <= ~q;
end

assign clk_out = q;

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

assign eq = (a == b);
assign gt = (a > b);
assign lt = (a < b);

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);
    wire n0, n1;
    wire e0, e1, e2, e3;

    assign n0 = ~in[0];
    assign n1 = ~in[1];

    assign e0 = ~(~(n1 | n0) & enable);
    assign e1 = ~(~(n1 | in[0]) & enable);
    assign e2 = ~(~(in[1] | n0) & enable);
    assign e3 = ~(~(in[1] | in[0]) & enable);

    assign out = {e3, e2, e1, e0};

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);

wire a, b, c;
assign a = in[2];
assign b = in[1];
assign c = in[0];

assign out[0] = ~(enable & ~a & ~b & ~c);
assign out[1] = ~(enable & ~a & ~b &  c);
assign out[2] = ~(enable & ~a &  b & ~c);
assign out[3] = ~(enable & ~a &  b &  c);
assign out[4] = ~(enable &  a & ~b & ~c);
assign out[5] = ~(enable &  a & ~b &  c);
assign out[6] = ~(enable &  a &  b & ~c);
assign out[7] = ~(enable &  a &  b &  c);

endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

assign out1 = in & sel;
assign out0 = ~(in & ~sel);

endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

assign out1 = in & sel[0];
assign out0 = ~(in & sel[0]);
assign out2 = 1'b0;
assign out3 = 1'b0;

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

reg [7:0] bin;

always @(posedge clk or posedge rst) begin
    if (rst)
        bin <= 8'b00000000;
    else
        bin <= bin + 8'b00000001;
end

assign count = bin ^ (bin >> 1);

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;

always @(posedge clk or posedge rst) begin
    if (rst)
        q_reg <= 4'b0000;
    else begin
        q_reg[0] <= ~q_reg[3];
        q_reg[1] <= q_reg[0];
        q_reg[2] <= q_reg[1];
        q_reg[3] <= q_reg[2];
    end
end

assign q = q_reg;

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

reg [7:0] shreg;

always @(posedge clk or posedge rst) begin
    if (rst)
        shreg <= 8'b0;
    else if (load)
        shreg <= pin;
    else
        shreg <= {shreg[6:0], 1'b0};
end

assign sout = shreg[7];

endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);

assign out[1] = in[3] | in[2];
assign out[0] = in[3] | (~in[2] & in[1]);
assign valid  = in[3] | in[2] | in[1] | in[0];

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;

always @(posedge clk or posedge rst) begin
    if (rst)
        q_reg <= 4'b0001;
    else
        q_reg <= {q_reg[2:0], q_reg[3]};
end

assign q = q_reg;

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);

reg [7:0] q;

always @(posedge clk or posedge rst) begin
    if (rst)
        q <= 8'b0;
    else begin
        q[0] <= sin;
        q[1] <= q[0];
        q[2] <= q[1];
        q[3] <= q[2];
        q[4] <= q[3];
        q[5] <= q[4];
        q[6] <= q[5];
        q[7] <= q[6];
    end
end

assign pout = q;

endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);

reg [7:0] shift_reg;

always @(posedge clk or posedge rst) begin
    if (rst)
        shift_reg <= 8'b0;
    else begin
        shift_reg[0] <= sin;
        shift_reg[1] <= shift_reg[0];
        shift_reg[2] <= shift_reg[1];
        shift_reg[3] <= shift_reg[2];
        shift_reg[4] <= shift_reg[3];
        shift_reg[5] <= shift_reg[4];
        shift_reg[6] <= shift_reg[5];
        shift_reg[7] <= shift_reg[6];
    end
end

assign sout = shift_reg[7];

endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

reg [7:0] count_reg;

always @(posedge clk or posedge rst) begin
    if (rst)
        count_reg <= 8'b00000000;
    else
        count_reg <= count_reg + 8'b00000001;
end

assign count = count_reg;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg q0, q1, q2;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
    end else begin
      q0 <= r[0];
      q1 <= r[1];
      q2 <= r[2];
    end
  end

  assign g[0] = q0;
  assign g[1] = q1;
  assign g[2] = q2;

endmodule

module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);

wire d;
wire en;

assign d = L ? R : w;
assign en = E | L;

always @(posedge clk) begin
  if (en)
    Q <= d;
end

endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

assign out_assign = a & b;

always @(*) begin
  out_alwaysblock = a & b;
end

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);

  wire x;

  assign x = a ^ b;
  assign out_assign = x;

  always @(*) begin
    out_always_comb = x;
  end

  always @(posedge clk) begin
    out_always_ff <= x;
  end

endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  wire sel;
  wire mux_out;

  assign sel = ~(sel_b1 & sel_b2);
  assign mux_out = sel ? b : a;
  assign out_assign = mux_out;

  always @(*) begin
    out_always = mux_out;
  end

endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

always @(*) begin
  shut_off_computer = cpu_overheated;
  keep_driving = ~(gas_tank_empty | arrived);
end

endmodule

module TopModule (
  input [15:0] scancode,
  output reg left,
  output reg down,
  output reg right,
  output reg up
);

always @(*) begin
  left  = (scancode == 16'h6B);
  down  = (scancode == 16'h72);
  right = (scancode == 16'h74);
  up    = (scancode == 16'h75);
end

endmodule

module TopModule (
  input a,
  input b,
  output out
);

assign out = a & b;

endmodule

module TopModule (
  input [7:0] code,
  output reg [3:0] out,
  output reg valid
);

always @(*) begin
  valid = |code;
  out = 4'b0000;

  casex (code)
    8'b1xxxxxxx: out = 4'd7;
    8'b01xxxxxx: out = 4'd6;
    8'b001xxxxx: out = 4'd5;
    8'b0001xxxx: out = 4'd4;
    8'b00001xxx: out = 4'd3;
    8'b000001xx: out = 4'd2;
    8'b0000001x: out = 4'd1;
    8'b00000001: out = 4'd0;
    default:    out = 4'd0;
  endcase
end

endmodule

module TopModule (
  input a,
  input b,
  output q
);

assign q = a & b;

endmodule

module TopModule (
  input clk,
  input a,
  output reg q
);

always @(posedge clk) begin
  q <= ~a;
end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  always @(posedge clk or posedge reset) begin
    if (reset)
      q <= 4'b0000;
    else
      q <= q + 4'b0001;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  reg q0, q1, q2, q3;
  reg [1:0] sel;
  wire n0, n1;
  wire nor1, nand1, nand2, xnor1, or1;
  wire mux_out;

  assign n0 = ~q0;
  assign n1 = ~q1;

  assign nor1  = ~(q0 | q1);
  assign nand1 = ~(q2 & q0);
  assign nand2 = ~(q2 & nand1);
  assign xnor1 = ~(nand2 ^ q3);
  assign or1   = q0 | q1;

  always @(*) begin
    case (sel)
      2'd0: q = {3'b000, q2};
      2'd1: q = {3'b000, q0};
      2'd2: q = {3'b000, nand1};
      2'd3: q = {3'b000, q3};
      default: q = 4'b0000;
    endcase
  end

  assign mux_out = (sel == 2'd0) ? q2 :
                   (sel == 2'd1) ? q0 :
                   (sel == 2'd2) ? nand1 :
                                   q3;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
      q3 <= 1'b0;
      sel <= 2'b00;
    end else begin
      q0 <= nor1;
      q1 <= q0;
      q2 <= xnor1;
      q3 <= mux_out;
      sel <= {n1, n0};
    end
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  wire q1, q2, q3, q4;
  wire d1, d2, d3, d4;
  wire r1, r2, r3, r4;

  assign r1 = reset;
  assign r2 = reset | (q1 & q3);
  assign r3 = reset;
  assign r4 = reset;

  assign d1 = ~q1;
  assign d2 = q1;
  assign d3 = q2 ^ q4;
  assign d4 = ~(q3 | q4);

  always @(posedge clk) begin
    if (r1)
      q[0] <= 1'b0;
    else
      q[0] <= d1;

    if (r2)
      q[1] <= 1'b0;
    else
      q[1] <= d2;

    if (r3)
      q[2] <= 1'b0;
    else
      q[2] <= d3;

    if (r4)
      q[3] <= 1'b0;
    else
      q[3] <= d4;
  end

  assign q1 = q[0];
  assign q2 = q[1];
  assign q3 = q[2];
  assign q4 = q[3];

endmodule

