  assign ns0 = ~reset & (w | s5);
  assign ns1 = ~reset & (~w & (s0 | s1));
  assign ns2 = ~reset & ((s1 & ~s3) | (w & s0));
  assign ns3 = ~reset & ((s2 | w) & ~s4);
  assign ns4 = ~reset & ((s3 & ~w) | s2);
  assign ns5 = ~reset & ((s4 | s5) & ~(s0 & w));

  always @(posedge clk) begin
    if (reset) begin
      s0 <= 1'b0;
      s1 <= 1'b0;
      s2 <= 1'b0;
      s3 <= 1'b0;
      s4 <= 1'b0;
      s5 <= 1'b0;
    end else begin
      s0 <= ns0;
      s1 <= ns1;
      s2 <= ns2;
