             C = 3'd2,
             D = 3'd3,
             E = 3'd4;

  always @(*) begin
    case (state)
      A: next_state = w ? B : A;
      B: next_state = w ? C : A;
      C: next_state = w ? C : D;
      D: next_state = w ? E : A;
      E: next_state = w ? C : A;
      default: next_state = A;
    endcase
  end

  always @(posedge clk or posedge reset) begin
    if (reset)
      state <= A;
    else
      state <= next_state;
  end

  assign z = (state == E);

