);
  always @(*) begin
    q[0] = (a == b) ? e[1] : e[0];
    q[1] = (c == d) ? b[0] : b[2];
    q[2] = (a > d) ? c[0] : c[3];
    q[3] = ((a[0] & b[1]) | (c[2] ^ d[3])) ? e[3] : e[2];
