module TopModule (
  input clk,
  input a,
  output reg [2:0] q
);

  wire q0, q1, q2;
  wire n0, n1, n2;
  wire w_and, w_nor, w_or, w_xor, w_nand;
  wire sel0, sel1, sel2;

  assign q0 = q[0];
  assign q1 = q[1];
  assign q2 = q[2];

  assign n0 = ~q0;
  assign w_and  = q0 & q1;
  assign w_nor  = ~(q1 | q0);
  assign sel0   = w_and | w_nor;
  assign sel1   = w_nor | n0;
  assign w_nand = ~(sel0 & sel1);
  assign n2     = ~q2;

  assign sel2 = n2;
  assign sel1 = q2;
  assign sel0 = w_xor;

  assign w_xor = q0 ^ q1;
  wire d2 = (sel2) ? 1'b0 : (sel1 ? 1'b1 : sel0);

  wire rr = ~(sel1 | sel0);
  wire d0 = rr ^ q1;
  wire d1 = q0;

  always @(posedge clk) begin
    q[0] <= d0;
    q[1] <= d1;
    if (a)
      q[2] <= 1'b0;
    else
      q[2] <= d2;
  end

endmodule

