  assign w0 = ~(s0 | s1);
  assign w1 = ~(w0 & s2);
  assign w2 = ~(s2 | s0);

  assign n0 = ~(s1 | s0);
  assign n1 = ~(nin & w1);
  assign n2 = ~(w1 & w2);
  assign n3 = ~(nin & w2);

  always @(*) begin
    next_state[0] = n0;
    next_state[1] = n1;
    next_state[2] = n2;
    next_state[3] = n3;
  end

