module TopModule (
  input clk,
  input reset,
  input in,
  output disc,
  output flag,
  output err
);

  reg [3:0] state, next_state;

  localparam S0 = 4'd0,
             S1 = 4'd1,
             S2 = 4'd2,
             S3 = 4'd3,
             S4 = 4'd4,
             S5 = 4'd5,
             S6 = 4'd6,
             S7 = 4'd7,
             S8 = 4'd8,
             S9 = 4'd9;

  always @(posedge clk or posedge reset) begin
    if (reset)
      state <= S0;
    else
      state <= next_state;
  end

  always @(*) begin
    case (state)
      S0: next_state = in ? S1 : S0;
      S1: next_state = in ? S2 : S0;
      S2: next_state = in ? S2 : S3;
      S3: next_state = in ? S4 : S0;
      S4: next_state = in ? S5 : S0;
      S5: next_state = in ? S2 : S6;
      S6: next_state = in ? S7 : S0;
      S7: next_state = in ? S8 : S0;
      S8: next_state = in ? S2 : S9;
      S9: next_state = in ? S1 : S0;
      default: next_state = S0;
    endcase
  end

  assign disc = (state == S9);
  assign flag = (state == S5) || (state == S8) || (state == S9);
  assign err  = (state == S6) || (state == S7);

endmodule

module TopModule (
  input in,
  input [9:0] state,
  output [9:0] next_state,
  output out1,
  output out2
);

