  wire s1 = state[1];
  wire s2 = state[2];
  wire s3 = state[3];
  wire s4 = state[4];
  wire s5 = state[5];
  wire s6 = state[6];
  wire s7 = state[7];
  wire s8 = state[8];
  wire s9 = state[9];

  wire top_or;
  wire mid_nor;
  wire low_nor;

  assign top_or  = s1 | s0 | s2 | s3 | s4;
  assign mid_nor = ~(s7 | s8);
  assign low_nor = ~(s0 | s1);

  assign next_state[0] = ~(top_or & s4);
  assign next_state[1] = ~(mid_nor & s9);
  assign next_state[2] = s5;
  assign next_state[3] = s6;
  assign next_state[4] = s3;
  assign next_state[5] = in;
  assign next_state[6] = s2;
  assign next_state[7] = ~(low_nor & s8);
  assign next_state[8] = ~(s7);
  assign next_state[9] = ~(s1);

  assign out1 = s0 | s2;
  assign out2 = s1 | s0;

endmodule

module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);

  wire n0, n1, n2, n3, n4, n5, n6, n7;
  wire q_done;

  assign n0 = in[3];
  assign n1 = ~(n0 | reset);
  assign n2 = ~(n0 & n1);
  assign n3 = n0 | clk;
  assign n4 = ~(n2 & n1);
  assign n5 = ~(clk & n3);
  assign n6 = n5 | n4;
  assign n7 = n6 | n4;

  dffre done_ff (
    .clk(clk),
    .r(n5),
    .en(1'b1),
    .d(n7),
    .q(q_done)
  );

  assign done = q_done;

endmodule

