module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  reg q0, q1, q2, q3, q4, q5, q6;

  wire nx = ~x;
  wire ny = ~y;

  wire d0 = (~resetn) ? 1'b0 : ((q0 & ~x) | (~q0 & y));
  wire d1 = (~resetn) ? 1'b0 : ((q1 & ~y) | (q0 & x));
  wire d2 = (~resetn) ? 1'b0 : ((q2 & ~q1) | (q1 & y));
  wire d3 = (~resetn) ? 1'b0 : ((q3 & ~x) | (q2 & ny));
  wire d4 = (~resetn) ? 1'b0 : ((q4 & ~q0) | (q3 & x));
  wire d5 = (~resetn) ? 1'b0 : ((q5 & ~q2) | (q4 & y));
  wire d6 = (~resetn) ? 1'b0 : ((q6 & ~q4) | (q5 & nx));

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
      q3 <= 1'b0;
      q4 <= 1'b0;
      q5 <= 1'b0;
      q6 <= 1'b0;
    end else begin
      q0 <= d0;
      q1 <= d1;
      q2 <= d2;
      q3 <= d3;
      q4 <= d4;
      q5 <= d5;
      q6 <= d6;
    end
  end

  assign f = (q6 & q3) | (~q5 & q2) | (x & q1) | (y & ~q4);
  assign g = (q6 & ~q0) | (q5 & q4) | (~q3 & x) | (q2 & y);

endmodule

