module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  wire s0 = state[0];
  wire s1 = state[1];
  wire s3 = state[3];
  wire s4 = state[4];
  wire s5 = state[5];
  wire s6 = state[6];
  wire s7 = state[7];
  wire s8 = state[8];
  wire s9 = state[9];

  assign counting = s8;
  assign done = s7;

  assign Count_next = (~s8 & done_counting) | s8;
  assign Wait_next  = (s8 & done_counting) | s7;
  assign shift_ena  = s4 | s5 | s6 | s3;

  assign S_next  = (s7 & ack) | (s7 & ~ack);
  assign B3_next = s8 | s9 | s5;

  assign S1_next = d & ~((s1 | s6 | s0) | s3);

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire c16;

     cla_16bit u0 (
          .A(A[16:1]),
          .B(B[16:1]),
          .Cin(1'b0),
          .S(S[16:1]),
          .Cout(c16)
     );

     cla_16bit u1 (
          .A(A[32:17]),
          .B(B[32:17]),
          .Cin(c16),
          .S(S[32:17]),
          .Cout(C32)
     );

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

wire [4:0] bin_sum;
wire       correction;
wire [4:0] bcd_sum;

assign bin_sum = A + B + Cin;
assign correction = bin_sum[4] | (bin_sum[3] & (bin_sum[2] | bin_sum[1]));
assign bcd_sum = bin_sum + (correction ? 5'd6 : 5'd0);

assign Sum = bcd_sum[3:0];
assign Cout = correction;

endmodule

module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

wire eq2, eq1, eq0;
wire gt2, gt1, gt0;
wire lt2, lt1, lt0;

assign eq2 = ~(A[2] ^ B[2]);
assign eq1 = ~(A[1] ^ B[1]);
assign eq0 = ~(A[0] ^ B[0]);

assign gt2 = A[2] & ~B[2];
assign gt1 = A[1] & ~B[1];
assign gt0 = A[0] & ~B[0];

assign lt2 = ~A[2] & B[2];
assign lt1 = ~A[1] & B[1];
assign lt0 = ~A[0] & B[0];

assign A_greater = gt2 | (eq2 & gt1) | (eq2 & eq1 & gt0);
assign A_less    = lt2 | (eq2 & lt1) | (eq2 & eq1 & lt0);
assign A_equal   = eq2 & eq1 & eq0;

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

assign A_equal   = (A == B);
assign A_greater = (A > B);
assign A_less    = (A < B);

endmodule

module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

always @(posedge clk or negedge rst_n) begin
  if (!rst_n)
    out <= 4'd0;
  else if (valid_count) begin
    if (out == 4'd11)
      out <= 4'd0;
    else
      out <= out + 4'd1;
  end
end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg a_d;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		a_d  <= 1'b0;
		rise <= 1'b0;
		down <= 1'b0;
	end else begin
		rise <= a & ~a_d;
		down <= ~a & a_d;
		a_d  <= a;
	end
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [31:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 32'd0;
            clk_div <= 1'b0;
        end else begin
            if (cnt == (NUM_DIV/2 - 1)) begin
                cnt <= 32'd0;
                clk_div <= ~clk_div;
            end else begin
                cnt <= cnt + 32'd1;
            end
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

reg [15:0] instr;

wire en_hi = ~(fetch[1] | fetch[0]);
wire en_lo = ~(fetch[1] | rst);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        instr <= 16'b0;
    end else begin
        if (en_hi)
            instr[15:8] <= data;
        if (en_lo)
            instr[7:0] <= data;
    end
end

assign ins = instr[15:13];
assign ad2 = instr[12:5];
assign ad1 = instr[4:0];

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire feedback;
  assign feedback = ~(out[1] ^ out[2]);

  always @(posedge clk or posedge rst) begin
    if (rst)
      out <= 4'b0000;
    else begin
      out[0] <= out[3];
      out[1] <= out[0];
      out[2] <= feedback;
      out[3] <= out[2];
    end
  end

endmodule

module right_shifter(clk, q,d);  

    input  clk;  
    input d;  
    output [7:0] q;

    reg [7:0] q;
    reg sel;

    always @(posedge clk) begin
        q <= {q[6:0], d};
        sel <= ~sel;
    end

    assign q[0] = sel ? q[7] : q[0];
    assign q[1] = sel ? q[6] : q[1];
    assign q[2] = sel ? q[5] : q[2];
    assign q[3] = sel ? q[4] : q[3];
    assign q[4] = sel ? q[3] : q[4];
    assign q[5] = sel ? q[2] : q[5];
    assign q[6] = sel ? q[1] : q[6];
    assign q[7] = sel ? q[0] : q[7];

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg        data_en_a;
reg [3:0]  data_a;

reg        data_en_b_ff1, data_en_b_ff2;
reg [3:0]  data_b_ff1;

always @(posedge clk_a or negedge arstn) begin
	if (!arstn)
		data_en_a <= 1'b0;
	else
		data_en_a <= data_en;
end

always @(posedge clk_b or negedge brstn) begin
	if (!brstn)
		data_en_b_ff1 <= 1'b0;
	else
		data_en_b_ff1 <= data_en_a;
end

always @(posedge clk_b or negedge brstn) begin
	if (!brstn)
		data_en_b_ff2 <= 1'b0;
	else
		data_en_b_ff2 <= data_en_b_ff1;
end

always @(posedge clk_a or negedge arstn) begin
	if (!arstn)
		data_a <= 4'b0000;
	else if (data_en_a)
		data_a <= data_in;
end

always @(posedge clk_b or negedge brstn) begin
	if (!brstn)
		data_b_ff1 <= 4'b0000;
	else
		data_b_ff1 <= data_a;
end

always @(posedge clk_b or negedge brstn) begin
	if (!brstn)
		dataout <= 4'b0000;
	else if (data_en_b_ff2)
		dataout <= data_b_ff1;
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg s0, s1, s2, s3, s4;
reg ns0, ns1, ns2, ns3, ns4;
reg nmatch;

always @(*) begin
    ns0 = s0;
    ns1 = s1;
    ns2 = s2;
    ns3 = s3;
    ns4 = s4;
    nmatch = MATCH;

    case ({s4,s3,s2,s1,s0})
        5'b00001: begin
            if (IN) begin
                ns0 = 1'b0;
                ns1 = 1'b1;
                ns2 = 1'b0;
                ns3 = 1'b0;
                ns4 = 1'b0;
                nmatch = 1'b0;
            end else begin
                ns0 = 1'b1;
                ns1 = 1'b0;
                ns2 = 1'b0;
                ns3 = 1'b0;
                ns4 = 1'b0;
                nmatch = 1'b0;
            end
        end
        5'b00010: begin
            if (IN) begin
                ns0 = 1'b0;
                ns1 = 1'b1;
                ns2 = 1'b0;
                ns3 = 1'b0;
                ns4 = 1'b0;
                nmatch = 1'b0;
            end else begin
                ns0 = 1'b0;
                ns1 = 1'b0;
                ns2 = 1'b1;
                ns3 = 1'b0;
                ns4 = 1'b0;
                nmatch = 1'b0;
            end
        end
        5'b00100: begin
            if (IN) begin
                ns0 = 1'b0;
                ns1 = 1'b0;
                ns2 = 1'b0;
                ns3 = 1'b1;
                ns4 = 1'b0;
                nmatch = 1'b0;
            end else begin
                ns0 = 1'b1;
                ns1 = 1'b0;
                ns2 = 1'b0;
                ns3 = 1'b0;
                ns4 = 1'b0;
                nmatch = 1'b0;
            end
        end
        5'b01000: begin
            if (IN) begin
                ns0 = 1'b0;
                ns1 = 1'b1;
                ns2 = 1'b0;
                ns3 = 1'b0;
                ns4 = 1'b0;
                nmatch = 1'b0;
            end else begin
                ns0 = 1'b0;
                ns1 = 1'b0;
                ns2 = 1'b0;
                ns3 = 1'b0;
                ns4 = 1'b1;
                nmatch = 1'b0;
            end
        end
        5'b10000: begin
            if (IN) begin
                ns0 = 1'b0;
                ns1 = 1'b1;
                ns2 = 1'b0;
                ns3 = 1'b0;
                ns4 = 1'b0;
                nmatch = 1'b1;
            end else begin
                ns0 = 1'b1;
                ns1 = 1'b0;
                ns2 = 1'b0;
                ns3 = 1'b0;
                ns4 = 1'b0;
                nmatch = 1'b0;
            end
        end
        default: begin
            ns0 = 1'b1;
            ns1 = 1'b0;
            ns2 = 1'b0;
            ns3 = 1'b0;
            ns4 = 1'b0;
            nmatch = 1'b0;
        end
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        s0 <= 1'b1;
        s1 <= 1'b0;
        s2 <= 1'b0;
        s3 <= 1'b0;
        s4 <= 1'b0;
        MATCH <= 1'b0;
    end else begin
        s0 <= ns0;
        s1 <= ns1;
        s2 <= ns2;
        s3 <= ns3;
        s4 <= ns4;
        MATCH <= nmatch;
    end
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shreg;
reg [2:0] cnt;
reg valid_r;
reg dout_r;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shreg   <= 4'b0000;
        cnt     <= 3'd0;
        valid_r <= 1'b0;
        dout_r  <= 1'b0;
    end else begin
        if (cnt == 3'd0) begin
            shreg   <= d;
            dout_r  <= d[3];
            valid_r <= 1'b1;
            cnt     <= 3'd1;
        end else if (cnt == 3'd1) begin
            shreg   <= {shreg[2:0], 1'b0};
            dout_r  <= shreg[2];
            valid_r <= 1'b1;
            cnt     <= 3'd2;
        end else if (cnt == 3'd2) begin
            shreg   <= {shreg[2:0], 1'b0};
            dout_r  <= shreg[1];
            valid_r <= 1'b1;
            cnt     <= 3'd3;
        end else begin
            shreg   <= {shreg[2:0], 1'b0};
            dout_r  <= shreg[0];
            valid_r <= 1'b1;
            cnt     <= 3'd0;
        end
    end
end

assign valid_out = valid_r;
assign dout = dout_r;

endmodule

module ROM (
    input wire [7:0] addr,        // 8-bit Address input
    output reg [15:0] dout        // 16-bit Data output
);

always @(*) begin
    case (addr)
        8'h00: dout = 16'h0003;
        8'h01: dout = 16'h0001;
        default: dout = 16'h0000;
    endcase
end

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

reg q0, q1, q2, q3, q4;

wire d0, d1, d2, d3, d4;

assign d0 = data_in;
assign d1 = q0 & ~data_in;
assign d2 = q1 & data_in;
assign d3 = q2 & ~data_in;
assign d4 = q3 & data_in;

assign sequence_detected = q4;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        q0 <= 1'b0;
        q1 <= 1'b0;
        q2 <= 1'b0;
        q3 <= 1'b0;
        q4 <= 1'b0;
    end else begin
        q0 <= d0;
        q1 <= d1;
        q2 <= d2;
        q3 <= d3;
        q4 <= d4;
    end
end

endmodule
